const VERSION="v4",PRECACHE="precache-v4",RUNTIME="runtime-v4",PRECACHE_URLS=["./","./index.html","./assets/styles/main.css","./assets/js/boot.min.js","./assets/fonts/schibsted-grotesk.woff2","./assets/fonts/jetbrains-mono.woff2","./assets/brand/mark-duo.svg","./manifest.json"];self.addEventListener("install",s=>{s.waitUntil(caches.open(PRECACHE).then(t=>t.addAll(PRECACHE_URLS)).then(()=>self.skipWaiting()))}),self.addEventListener("activate",s=>{const t=[PRECACHE,RUNTIME];s.waitUntil(caches.keys().then(c=>Promise.all(c.filter(e=>!t.includes(e)).map(e=>caches.delete(e)))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",s=>{const t=s.request;if(t.method!=="GET")return;const c=new URL(t.url);if(c.origin===self.location.origin&&!c.pathname.includes("/assets/js/world/")){if(t.mode==="navigate"){s.respondWith(fetch(t).then(e=>{if(e.ok){const a=e.clone();caches.open(RUNTIME).then(n=>n.put(t,a))}return e}).catch(()=>caches.match(t).then(e=>e||caches.match("./index.html"))));return}s.respondWith(caches.match(t).then(e=>{const a=fetch(t).then(n=>{if(n.ok){const i=n.clone();caches.open(RUNTIME).then(o=>o.put(t,i))}return n}).catch(()=>e);return e||a}))}});
